content.content:
     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * 프로그램 전체 코드 생성
    21→   */
    22→  generate(program: AST.Program): CodegenResult {
    23→    // @mode 마커는 무시하고 함수/문장만 처리
    24→    for (const item of program.body) {
    25→      const fnItem = item as any;
    26→      if (fnItem.type === 'VFunction') {
    27→        this.genVFunction(fnItem as AST.VFunction);
    28→      } else if (fnItem.type === 'PyFunction') {
    29→        this.genPyFunction(fnItem as AST.PyFunction);
    30→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    31→        // 탑레벨 문장은 V 모드(C)로 처리
    32→        this.genVStatement(fnItem as AST.Statement);
    33→      }
    34→    }
    35→
    36→    const c = this.cLines.join('\n');
    37→    const python = this.pyLines.join('\n');
    38→
    39→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    40→    const mixed =
    41→      c && python
    42→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    43→        : c || python;
    44→
    45→    return { c, python, mixed };
    46→  }
    47→
    48→  /**
    49→   * 실행 가능한 프로그램 생성
    50→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    51→   */
    52→  generateProgram(program: AST.Program): CodegenResult {
    53→    const base = this.generate(program);
    54→
    55→    // C 코드에 헤더 + main() wrapping 추가
    56→    const cWithMain = base.c
    57→      ? `#include <stdio.h>\n#include <stdbool.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    58→      : '';
    59→
    60→    // Python 코드에 main 블록 추가
    61→    const pyWithMain = base.python
    62→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    63→      : '';
    64→
    65→    return {
    66→      c: cWithMain,
    67→      python: pyWithMain,
    68→      mixed: base.mixed,
    69→    };
    70→  }
    71→
    72→  /**
    73→   * V 함수 → C 함수
    74→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    75→   * →
    76→   * long long add(long long x, long long y) { return x + y; }
    77→   */
    78→  private genVFunction(fn: AST.VFunction): void {
    79→    // 반환타입
    80→    const returnType = this.mapVType(fn.returnType || 'void');
    81→
    82→    // 파라미터 리스트
    83→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    84→
    85→    // 함수 시그니처
    86→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    87→
    88→    // 함수 본문
    89→    this.indentLevel++;
    90→    for (const stmt of fn.body) {
    91→      this.genVStatement(stmt);
    92→    }
    93→    this.indentLevel--;
    94→
    95→    this.writeC('}');
    96→    this.writeC(''); // 빈 줄
    97→  }
    98→
    99→  /**
   100→   * Python 함수 → Python 함수
   101→   * def slow(items): return items
   102→   * →
   103→   * def slow(items):
   104→   *     return items
   105→   */
   106→  private genPyFunction(fn: AST.PyFunction): void {
   107→    // 파라미터 리스트
   108→    const paramList = fn.params.map((p) => p.name).join(', ');
   109→
   110→    // 함수 정의
   111→    this.writePy(`def ${fn.name}(${paramList}):`);
   112→
   113→    // 함수 본문 (들여쓰기 필요)
   114→    this.indentLevel++;
   115→    for (const stmt of fn.body) {
   116→      this.genPyStatement(stmt);
   117→    }
   118→    this.indentLevel--;
   119→
   120→    this.writePy(''); // 빈 줄
   121→  }
   122→
   123→  /**
   124→   * V 문장 생성 (C 코드용)
   125→   */
   126→  private genVStatement(stmt: AST.Statement): void {
   127→    const s = stmt as any;
   128→
   129→    if (s.type === 'Return') {
   130→      const returnStmt = s as AST.ReturnStatement;
   131→      if (returnStmt.value) {
   132→        const expr = this.genVExpression(returnStmt.value);
   133→        this.writeC(`${this.indent()}return ${expr};`);
   134→      } else {
   135→        this.writeC(`${this.indent()}return;`);
   136→      }
   137→    } else if (s.type === 'Assign') {
   138→      const assignStmt = s as AST.AssignStatement;
   139→      const expr = this.genVExpression(assignStmt.value);
   140→      // C에서는 타입을 추론할 수 없으므로 기본값으로 long long 사용
   141→      this.writeC(`${this.indent()}long long ${assignStmt.name} = ${expr};`);
   142→    } else if (s.type === 'ExprStatement') {
   143→      const exprStmt = s as AST.ExprStatement;
   144→      const expr = this.genVExpression(exprStmt.expression);
   145→      this.writeC(`${this.indent()}${expr};`);
   146→    }
   147→  }
   148→
   149→  /**
   150→   * Python 문장 생성 (Python 코드용)
   151→   */
   152→  private genPyStatement(stmt: AST.Statement): void {
   153→    const s = stmt as any;
   154→    const indentStr = this.indent();
   155→
   156→    if (s.type === 'Return') {
   157→      const returnStmt = s as AST.ReturnStatement;
   158→      if (returnStmt.value) {
   159→        const expr = this.genPyExpression(returnStmt.value);
   160→        this.writePy(`${indentStr}return ${expr}`);
   161→      } else {
   162→        this.writePy(`${indentStr}return`);
   163→      }
   164→    } else if (s.type === 'Assign') {
   165→      const assignStmt = s as AST.AssignStatement;
   166→      const expr = this.genPyExpression(assignStmt.value);
   167→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   168→    } else if (s.type === 'ExprStatement') {
   169→      const exprStmt = s as AST.ExprStatement;
   170→      const expr = this.genPyExpression(exprStmt.expression);
   171→      this.writePy(`${indentStr}${expr}`);
   172→    }
   173→  }
   174→
   175→  /**
   176→   * V 표현식 생성 (C 코드용)
   177→   */
   178→  private genVExpression(expr: AST.Expression): string {
   179→    const e = expr as any;
   180→
   181→    if (e.type === 'Number') {
   182→      return (e as AST.NumberLiteral).value.toString();
   183→    }
   184→
   185→    if (e.type === 'String') {
   186→      return `"${(e as AST.StringLiteral).value}"`;
   187→    }
   188→
   189→    if (e.type === 'Identifier') {
   190→      return (e as AST.Identifier).name;
   191→    }
   192→
   193→    if (e.type === 'BinaryExpr') {
   194→      const binExpr = e as AST.BinaryExpr;
   195→      const left = this.genVExpression(binExpr.left);
   196→      const right = this.genVExpression(binExpr.right);
   197→      return `${left} ${binExpr.operator} ${right}`;
   198→    }
   199→
   200→    if (e.type === 'Call') {
   201→      const callExpr = e as AST.CallExpr;
   202→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   203→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   204→      return `${callee}(${args})`;
   205→    }
   206→
   207→    return '';
   208→  }
   209→
   210→  /**
   211→   * Python 표현식 생성 (Python 코드용)
   212→   */
   213→  private genPyExpression(expr: AST.Expression): string {
   214→    const e = expr as any;
   215→
   216→    if (e.type === 'Number') {
   217→      return (e as AST.NumberLiteral).value.toString();
   218→    }
   219→
   220→    if (e.type === 'String') {
   221→      return `"${(e as AST.StringLiteral).value}"`;
   222→    }
   223→
   224→    if (e.type === 'Identifier') {
   225→      return (e as AST.Identifier).name;
   226→    }
   227→
   228→    if (e.type === 'BinaryExpr') {
   229→      const binExpr = e as AST.BinaryExpr;
   230→      const left = this.genPyExpression(binExpr.left);
   231→      const right = this.genPyExpression(binExpr.right);
   232→      return `${left} ${binExpr.operator} ${right}`;
   233→    }
   234→
   235→    if (e.type === 'Call') {
   236→      const callExpr = e as AST.CallExpr;
   237→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   238→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   239→      return `${callee}(${args})`;
   240→    }
   241→
   242→    return '';
   243→  }
   244→
   245→  /**
   246→   * V 타입 → C 타입 매핑
   247→   */
   248→  private mapVType(type: string): string {
   249→    const mapping: Record<string, string> = {
   250→      i64: 'long long',
   251→      i32: 'int',
   252→      f64: 'double',
   253→      f32: 'float',
   254→      bool: 'bool',
   255→      string: 'char*',
   256→      void: 'void',
   257→    };
   258→
   259→    return mapping[type] || type;
   260→  }
   261→
