  /**
   * Python 코드에 줄 추가
   */
  private writePy(line: string): void {
    this.pyLines.push(line);
  }

  /**
   * 현재 들여쓰기 문자열
   */
  private indent(): string {
    return '    '.repeat(this.indentLevel);
  }
}

