/**
 * FreeLang Nexus Parser - 단위 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import * as AST from '../src/nexus/parser/ast';

describe('NexusParser - Phase 2 핵심 테스트', () => {
  // ==================== Test 1: V 함수 기본 파싱 ====================
  test('V 함수 기본: fn hello() {}', () => {
    const source = `@mode(v)
fn hello() {
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    expect(ast.type).toBe('Program');
    expect(ast.body.length).toBeGreaterThan(0);

    const fn = ast.body[0] as AST.VFunction;
    expect(fn.type).toBe('VFunction');
    expect(fn.name).toBe('hello');
    expect(fn.params.length).toBe(0);
    expect(fn.body.length).toBe(0);
    expect(fn.mode).toBe('v');
  });

