    const code = `@mode(v)
fn test() -> void {
  println("hello")
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('printf');
  });

  /**
   * Test 2: println("hello") → C 코드에 \n 포함 (개행 자동 추가)
   */
  test('Test 2: println → 개행(\\n) 자동 추가', () => {
    const code = `@mode(v)
fn test() -> void {
  println("hello")
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('\\n');
  });

  /**
   * Test 3: print("hello") → C 코드에 printf 포함 (개행 없음)
   */
  test('Test 3: print → 개행 없음', () => {
    const code = `@mode(v)
fn test() -> void {
  print("hello")
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('printf');
    // print는 개행 없어야 함
    const hasNewlineInPrint = result.c.includes('printf(') && result.c.includes('\\n');
    expect(hasNewlineInPrint).toBe(false);
  });

  /**
   * Test 4: len(s) → C 코드에 strlen 포함
   */
  test('Test 4: len → strlen 매핑', () => {
    const code = `@mode(v)
fn test() -> void {
  len("hello")
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('strlen');
  });

  /**
   * Test 5: 전체 파이프라인: println 함수 포함 소스 → 컴파일 성공
   */
  test('Test 5: generateProgram → stdio.h, string.h, main() 포함', () => {
    const code = `@mode(v)
fn greet() -> void {
  println("Hello, world!")
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generateProgram(ast);

    // C 헤더 확인
    expect(result.c).toContain('#include <stdio.h>');
    expect(result.c).toContain('#include <string.h>');
    expect(result.c).toContain('int main()');
  });

  /**
   * Test 6: println(x) (비 문자열 arg) → C 코드에 %lld 포함
   */
  test('Test 6: println 숫자 인자 → %lld 포맷 적용', () => {
    const code = `@mode(v)
fn test() -> void {
  println(42)
}`;
    const lexer = new NexusLexer(code);
