private parsePrimary(): AST.Expression {
  const token = this.peek();

  // 숫자
  if (token.type === TokenType.NUMBER) {
    this.advance();
    return {
      type: 'Number',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 문자열
  if (token.type === TokenType.STRING) {
    this.advance();
    return {
      type: 'String',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // true, false
  if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
    this.advance();
    return {
      type: 'Number',
      value: token.type === TokenType.TRUE ? 1 : 0,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 식별자
  if (token.type === TokenType.IDENTIFIER) {
    this.advance();
    return {
      type: 'Identifier',
      name: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
