/**
 * FreeLang Nexus - 통합 Parser
 * V 모드 + Python 모드 함수를 혼합하여 파싱
 */

import { Token, TokenType } from '../lexer/token';
import * as AST from './ast';

export class NexusParser {
  private tokens: Token[];
  private pos: number = 0;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  /**
   * 파싱 진입점
   */
  parse(): AST.Program {
    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];

    while (!this.isAtEnd()) {
      this.skipNewlines();
      if (this.isAtEnd()) break;

      const token = this.peek();

      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
      if (token.type === TokenType.MODE_MARKER) {
        this.advance();
        continue;
      }

      // 탑레벨 아이템 파싱
      const item = this.parseTopLevel();
      if (item) {
        body.push(item);
      }
    }

    return { type: 'Program', body };
  }

  /**
   * 탑레벨 아이템 파싱
   * V 함수, Python 함수, 또는 문장
   */
  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    const token = this.peek();

    // V 모드 함수
    if (token.type === TokenType.FN) {
      return this.parseVFunction();
    }

    // Python 모드 함수
    if (token.type === TokenType.DEF) {
      return this.parsePyFunction();
    }

    // 그 외: 문장
    return this.parseStatement();
  }

  /**
   * V 함수 파싱
   * fn name(params) -> type { body }
   */
  private parseVFunction(): AST.VFunction {
    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    const name = nameToken.value;

    this.consume(TokenType.LPAREN, '( 필요');
    const params = this.parseVParams();
    this.consume(TokenType.RPAREN, ') 필요');

    const returnType = this.parseReturnType();

    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'VFunction',
      name,
      params,
      returnType,
      body,
      mode: 'v',
      line: startToken.line,
      column: startToken.column,
    };
  }

  /**
   * Python 함수 파싱
   * def name(params): INDENT body DEDENT
   */
  private parsePyFunction(): AST.PyFunction {
    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    const name = nameToken.value;

    this.consume(TokenType.LPAREN, '( 필요');
    const params = this.parsePyParams();
    this.consume(TokenType.RPAREN, ') 필요');

    const returnType = this.parseReturnType();

    this.consume(TokenType.COLON, ': 필요');
    this.skipNewlines();

    const body = this.parsePyBlock();

    return {
      type: 'PyFunction',
      name,
      params,
      returnType,
      body,
      mode: 'python',
      line: startToken.line,
      column: startToken.column,
    };
  }

  /**
   * V 함수 파라미터 파싱
   * (x: i64, y: i64)
   */
  private parseVParams(): AST.Parameter[] {
    const params: AST.Parameter[] = [];

    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
      this.consume(TokenType.COLON, ': 필요');
      const typeToken = this.peek();
      const typeAnnotation = this.parseType();

      params.push({
        name: nameToken.value,
        typeAnnotation,
        line: nameToken.line,
        column: nameToken.column,
      });

      if (!this.check(TokenType.RPAREN)) {
        this.consume(TokenType.COMMA, ', 필요');
      }
    }

    return params;
  }

  /**
   * Python 함수 파라미터 파싱
   * (x, y) 또는 (x: int, y: int)
   */
  private parsePyParams(): AST.Parameter[] {
    const params: AST.Parameter[] = [];

    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
      let typeAnnotation: string | undefined;

      // 타입 어노테이션 (선택)
      if (this.check(TokenType.COLON)) {
        this.advance();
        typeAnnotation = this.parseType();
      }

      params.push({
        name: nameToken.value,
        typeAnnotation,
        line: nameToken.line,
        column: nameToken.column,
      });

      if (!this.check(TokenType.RPAREN)) {
        this.consume(TokenType.COMMA, ', 필요');
      }
    }

    return params;
  }

  /**
   * 반환 타입 파싱
   * -> i64 (선택)
   */
  private parseReturnType(): string | undefined {
    if (this.match(TokenType.ARROW)) {
      return this.parseType();
    }
    return undefined;
  }

  /**
   * 타입 파싱
   * i64, string, bool 등
   */
  private parseType(): string {
    const token = this.peek();

    // 기본 타입
    if (
      token.type === TokenType.I64 ||
      token.type === TokenType.I32 ||
      token.type === TokenType.F64 ||
      token.type === TokenType.BOOL ||
      token.type === TokenType.STRING ||
      token.type === TokenType.IDENTIFIER
    ) {
      return this.advance().value;
    }

    throw new Error(`타입 필요 at line ${token.line}`);
  }

  /**
   * V 블록 파싱
   * { statements }
   */
  private parseVBlock(): AST.Statement[] {
    const statements: AST.Statement[] = [];

    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
      this.skipNewlines();

      if (this.check(TokenType.RBRACE)) break;

      const stmt = this.parseStatement();
      if (stmt) {
        statements.push(stmt);
      }

      this.skipNewlines();
    }

    return statements;
  }

  /**
   * Python 블록 파싱
   * INDENT statements DEDENT
   */
  private parsePyBlock(): AST.Statement[] {
    const statements: AST.Statement[] = [];

    this.consume(TokenType.INDENT, 'INDENT 필요');

    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
      this.skipNewlines();

      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;

      const stmt = this.parseStatement();
      if (stmt) {
        statements.push(stmt);
      }

      this.skipNewlines();
    }

    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
    if (this.check(TokenType.DEDENT)) {
      this.advance();
    }

    return statements;
  }

  /**
   * 문장 파싱
   */
  private parseStatement(): AST.Statement {
    const token = this.peek();

    // return 문장
    if (token.type === TokenType.RETURN) {
      return this.parseReturnStatement();
    }

    // pass 문장 (Python)
    if (token.type === TokenType.PASS) {
      const passToken = this.advance();
      return {
        type: 'ExprStatement',
        expression: {
          type: 'Identifier',
          name: 'pass',
          line: passToken.line,
          column: passToken.column,
          mode: passToken.mode,
        },
        line: passToken.line,
        column: passToken.column,
        mode: passToken.mode,
      };
    }

    // let 또는 식별자 (할당 가능성)
    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
      return this.parseAssignOrExpr();
    }

    // 기본값: 표현식 문장
    const expr = this.parseExpression();
    const startToken = this.peek();
    return {
      type: 'ExprStatement',
      expression: expr,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * Return 문장 파싱
   */
  private parseReturnStatement(): AST.ReturnStatement {
    const startToken = this.consume(TokenType.RETURN, 'return 필요');
    let value: AST.Expression | undefined;

    // 반환값이 있으면 파싱
    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
      value = this.parseExpression();
    }

    return {
      type: 'Return',
      value,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 할당 또는 표현식 파싱
   */
  private parseAssignOrExpr(): AST.Statement {
    const startToken = this.peek();

    // let x = value
    if (startToken.type === TokenType.LET) {
      this.advance();
      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
      this.consume(TokenType.EQUAL, '= 필요');
      const value = this.parseExpression();

      return {
        type: 'Assign',
        name: nameToken.value,
        value,
        line: startToken.line,
        column: startToken.column,
        mode: startToken.mode,
      };
    }

    // x = value
    if (startToken.type === TokenType.IDENTIFIER) {
      const nameToken = this.peek();
      const name = nameToken.value;
      this.advance();

      if (this.check(TokenType.EQUAL)) {
        this.advance();
        const value = this.parseExpression();

        return {
          type: 'Assign',
          name,
          value,
          line: startToken.line,
          column: startToken.column,
          mode: startToken.mode,
        };
      }

      // 아니면 식별자는 표현식으로 처리
      const expr: AST.Identifier = {
        type: 'Identifier',
        name,
        line: nameToken.line,
        column: nameToken.column,
        mode: nameToken.mode,
      };

      return {
        type: 'ExprStatement',
        expression: expr,
        line: startToken.line,
        column: startToken.column,
        mode: startToken.mode,
      };
    }

    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
  }

  /**
   * 표현식 파싱
   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   */
  private parseExpression(): AST.Expression {
    return this.parseLogicalOr();
  }

  /**
   * 논리 OR 파싱: ||
   */
  private parseLogicalOr(): AST.Expression {
    let expr = this.parseLogicalAnd();

    while (this.match(TokenType.OR)) {
      const operator = this.previous().value;
      const right = this.parseLogicalAnd();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 논리 AND 파싱: &&
   */
  private parseLogicalAnd(): AST.Expression {
    let expr = this.parseEquality();

    while (this.match(TokenType.AND)) {
      const operator = this.previous().value;
      const right = this.parseEquality();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 등호/부등호 파싱: ==, !=
   */
  private parseEquality(): AST.Expression {
    let expr = this.parseComparison();

    while (this.match(TokenType.EQ, TokenType.NE)) {
      const operator = this.previous().value;
      const right = this.parseComparison();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 비교 파싱: <, >, <=, >=
   */
  private parseComparison(): AST.Expression {
    let expr = this.parseAddition();

    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
      const operator = this.previous().value;
      const right = this.parseAddition();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 덧셈/뺄셈 파싱
   */
  private parseAddition(): AST.Expression {
    let expr = this.parseMultiplication();

    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
      const operator = this.previous().value;
      const right = this.parseMultiplication();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 곱셈/나눗셈 파싱
   */
  private parseMultiplication(): AST.Expression {
    let expr = this.parseUnary();

    while (this.match(TokenType.STAR, TokenType.SLASH)) {
      const operator = this.previous().value;
      const right = this.parseUnary();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 단항 연산 파싱
   */
  private parseUnary(): AST.Expression {
    // TODO: 단항 연산자 (-, !, ~) 처리 가능
    return this.parsePostfix();
  }

  /**
   * 후위 연산 파싱 (함수 호출, 멤버 접근)
   */
  private parsePostfix(): AST.Expression {
    let expr = this.parsePrimary();

    while (true) {
      // 함수 호출: foo()
      if (this.match(TokenType.LPAREN)) {
        const args = this.parseArguments();
        this.consume(TokenType.RPAREN, ') 필요');

        const token = this.previous();
        expr = {
          type: 'Call',
          callee: expr,
          args,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      } else {
        break;
      }
    }

    return expr;
  }

  /**
   * 기본 표현식 파싱 (리터럴, 식별자 등)
   */
  private parsePrimary(): AST.Expression {
    const token = this.peek();

    // 숫자
    if (token.type === TokenType.NUMBER) {
      this.advance();
      return {
        type: 'Number',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 문자열
    if (token.type === TokenType.STRING) {
      this.advance();
      return {
        type: 'String',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // true, false
    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
      this.advance();
      return {
        type: 'Number',
        value: token.type === TokenType.TRUE ? 1 : 0,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 식별자
    if (token.type === TokenType.IDENTIFIER) {
      this.advance();
      return {
        type: 'Identifier',
        name: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 괄호 식
    if (this.match(TokenType.LPAREN)) {
      const expr = this.parseExpression();
      this.consume(TokenType.RPAREN, ') 필요');
      return expr;
    }

    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
  }

  /**
   * 함수 호출 인자 파싱
   */
  private parseArguments(): AST.Expression[] {
    const args: AST.Expression[] = [];

    if (!this.check(TokenType.RPAREN)) {
      do {
        args.push(this.parseExpression());
      } while (this.match(TokenType.COMMA));
    }

    return args;
  }

  // ========== 헬퍼 메서드 ==========

  private peek(): Token {
    if (this.pos >= this.tokens.length) {
      return this.tokens[this.tokens.length - 1]; // EOF 토큰
    }
    return this.tokens[this.pos];
  }

  private advance(): Token {
    if (!this.isAtEnd()) {
      this.pos++;
    }
    return this.previous();
  }

  private previous(): Token {
    return this.tokens[this.pos - 1];
  }

  private isAtEnd(): boolean {
    return this.peek().type === TokenType.EOF;
  }

  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private match(...types: TokenType[]): boolean {
    for (const type of types) {
      if (this.check(type)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private consume(type: TokenType, message: string): Token {
    if (this.check(type)) return this.advance();

    const token = this.peek();
    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
  }

  private skipNewlines(): void {
    while (this.match(TokenType.NEWLINE)) {
      // 계속
    }
  }
}

