private tokenizeString(): Token {
  const start = this.pos;
  let isFString = false;

  // f-string 확인
  if (this.peek() === 'f' && (this.peek(1) === '"' || this.peek(1) === "'")) {
    isFString = true;
    this.advance(); // 'f'
  }

  const quote = this.peek();
  this.advance(); // 첫 따옴표

  // 3중 따옴표 확인
  let isTriple = false;
  if (this.peek() === quote && this.peek(1) === quote) {
    isTriple = true;
    this.advance();
    this.advance();
  }

  // 문자열 내용 읽기
  while (this.pos < this.source.length) {
    const ch = this.peek();

    if (isTriple) {
      if (ch === quote && this.peek(1) === quote && this.peek(2) === quote) {
        this.advance();
        this.advance();
        this.advance();
        break;
      }
    } else {
      if (ch === quote) {
        this.advance();
        break;
      }
      if (ch === '\n') {
        throw new Error(`Unterminated string at line ${this.line}`);
      }
    }

    if (ch === '\\') {
      this.advance(); // 이스케이프 문자 다음
      if (this.pos < this.source.length) {
        this.advance();
      }
    } else {
      this.advance();
    }
  }

  const value = this.source.substring(start, this.pos);
  return this.makeToken(TokenType.STRING, value, this.currentMode);
}

