 * V 모드 내장 함수 호출 생성
 */
private genVBuiltinCall(name: string, args: AST.Expression[]): string {
  const argExprs = args.map((arg) => this.genVExpression(arg));

  if (name === 'println') {
    if (argExprs.length === 0) return 'printf("\\n")';
    const firstArg = args[0] as any;
    // StringLiteral인 경우: printf의 format string으로 사용
    if (firstArg.type === 'String') {
      // argExprs[0]은 이미 "..." 형태이므로 format string으로 직접 사용
      const str = argExprs[0].slice(1, -1); // 따옴표 제거
      return `printf("${str}\\n")`;
    }
    // 숫자/식별자인 경우 %lld 포맷 사용
    return `printf("%lld\\n", ${argExprs[0]})`;
  }

  if (name === 'print') {
    if (argExprs.length === 0) return 'printf("")';
    const firstArg = args[0] as any;
    if (firstArg.type === 'String') {
      // StringLiteral인 경우: printf의 format string으로 사용
      const str = argExprs[0].slice(1, -1); // 따옴표 제거
      return `printf("${str}")`;
    }
    return `printf("%lld", ${argExprs[0]})`;
  }

  if (name === 'len') {
    return `strlen(${argExprs[0]})`;
  }

  if (name === 'to_string') {
    return argExprs[0]; // 단순 pass-through
  }

  return '';
}

