import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

describe('FreeLang Nexus Phase 8 - Stdlib 추가 확장', () => {
  /**
   * Test 1: int_cast("42") → C 코드에 atoi 포함
   */
  test('Test 1: int_cast 문자열 리터럴 → atoi 생성', () => {
    const code = `@mode(v)
fn test() -> i64 {
  int_cast("42")
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('atoi');
  });

  /**
   * Test 2: int_cast(x) → C 코드에 atoi(x) 포함
   */
  test('Test 2: int_cast 식별자 인자 → atoi(x) 매핑', () => {
    const code = `@mode(v)
fn test() -> i64 {
  int_cast(s)
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('atoi');
  });

  /**
   * Test 3: generateProgram → stdlib.h 포함
   */
  test('Test 3: generateProgram → #include <stdlib.h> 포함', () => {
    const code = `@mode(v)
fn test() -> i64 {
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generateProgram(ast);

    expect(result.c).toContain('#include <stdlib.h>');
  });

  /**
   * Test 4: if condition { body } → C 코드에 if 포함
   */
  test('Test 4: if 문장 → C if 포함', () => {
    const code = `@mode(v)
fn test() -> i64 {
  if x > 0 {
    return 1
  }
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('if (');
    expect(result.c).toContain('x > 0');
  });

  /**
   * Test 5: if...else → C 코드에 else 포함
   */
  test('Test 5: if/else → C else 포함', () => {
    const code = `@mode(v)
fn test() -> i64 {
  if x > 0 {
    return 1
  } else {
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('else {');
  });

  /**
   * Test 6: if 블록 내 println 사용 → printf 포함
   */
  test('Test 6: if 블록 내 println → printf 포함', () => {
    const code = `@mode(v)
fn test() -> i64 {
  if x > 0 {
    println("positive")
  }
  return 0
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    expect(result.c).toContain('printf');
    expect(result.c).toContain('if (');
  });

  /**
   * Test 7: int_cast + if/else 혼합 → 전체 파이프라인 검증
   */
  test('Test 7: int_cast + if/else 혼합 → 전체 파이프라인', () => {
    const code = `@mode(v)
fn parse_count(s: string) -> i64 {
  let count = int_cast(s)
  if count > 10 {
    println("large")
    return 1
  } else {
    println("small")
    return 0
  }
}`;
    const lexer = new NexusLexer(code);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generateProgram(ast);

    // 전체 검증
    expect(result.c).toContain('#include <stdlib.h>');
    expect(result.c).toContain('atoi');
    expect(result.c).toContain('if (');
    expect(result.c).toContain('else {');
    expect(result.c).toContain('printf');
    expect(result.c).toContain('int main()');
  });
});

